const form=document.getElementById("mortgageForm"),result=document.getElementById("result");form&&form.addEventListener("submit",s=>{s.preventDefault();const o=parseFloat(document.getElementById("price").value)||0,r=parseFloat(document.getElementById("down").value)||0,c=parseFloat(document.getElementById("years").value)||20,i=parseFloat(document.getElementById("rate").value)||16,t=o-r;if(t<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Первоначальный взнос должен быть меньше стоимости жилья.</p>';return}const n=Math.max(1,Math.round(c*12)),a=i/100/12,e=a===0?t/n:t*a/(1-Math.pow(1+a,-n)),l=e*n,m=l-t;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Сумма кредита</span><span class="val">${fmt(t)} ₽</span></div>
        <div class="item total"><span>Ежемесячный платёж</span><span class="val">${fmt(e)} ₽</span></div>
        <div class="item"><span>Переплата по процентам</span><span class="val">${fmt(m)} ₽</span></div>
        <div class="item"><span>Всего выплат</span><span class="val">${fmt(l)} ₽</span></div>
      </div>
      <p class="hint" style="margin-top:14px">Аннуитетный платёж ${fmt(e)} ₽ × ${n} мес.</p>
    `});function fmt(s){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:0}).format(s)}
